&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;30 days annual PTO plus b/h&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
